const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE"; // 13.3 x 7.5

// Palette — Midnight Executive
const NAVY = "1E2761";
const NAVY_DEEP = "141B4A";
const ICE = "CADCFC";
const WHITE = "FFFFFF";
const MUTED = "6B7A99";
const ACCENT = "F0B429"; // warm accent for callouts
const CARD = "F5F7FB";
const CODE_BG = "0E1330";
const CODE_TXT = "E7ECFF";

const HEADER_FONT = "Cambria";
const BODY_FONT = "Calibri";
const MONO_FONT = "Courier New";

const SLIDE_W = 13.3;
const SLIDE_H = 7.5;

function addFooter(slide, num) {
  slide.addText("skillpp — team intro", {
    x: 0.5, y: 7.1, w: 6, h: 0.3,
    fontFace: BODY_FONT, fontSize: 10, color: MUTED, isTextBox: true, margin: 0,
  });
  slide.addText(`${num} / 5`, {
    x: SLIDE_W - 1.2, y: 7.1, w: 0.7, h: 0.3,
    fontFace: BODY_FONT, fontSize: 10, color: MUTED, align: "right",
    isTextBox: true, margin: 0,
  });
}

function addTitle(slide, text) {
  slide.addText(text, {
    x: 0.5, y: 0.4, w: SLIDE_W - 1.0, h: 0.9,
    fontFace: HEADER_FONT, fontSize: 36, bold: true, color: NAVY,
    isTextBox: true, margin: 0,
  });
}

function codeBox(slide, x, y, w, h, lines) {
  slide.addShape(pres.ShapeType.roundRect, {
    x, y, w, h, fill: { color: CODE_BG }, line: { color: CODE_BG }, rectRadius: 0.08,
  });
  const body = lines.map((t, i) => ({
    text: t, options: { fontFace: MONO_FONT, fontSize: 13, color: CODE_TXT, breakLine: i < lines.length - 1 },
  }));
  slide.addText(body, {
    x: x + 0.15, y: y + 0.1, w: w - 0.3, h: h - 0.2,
    isTextBox: true, margin: 0, valign: "top",
  });
}

